import type { PlayerId, PlayerKind, PlayerProfile } from '../contracts/game';
import type { MatchStanding } from './types';

export const DEFAULT_RATING = 1000;

export interface RatingParticipant {
  playerId: PlayerId;
  rating: number;
  /** 1-based finishing place; equal places count as a tie. */
  place: number;
  matchesPlayed?: number;
  kind?: PlayerKind;
}

export interface RatingOptions {
  baseK?: number;
  provisionalK?: number;
  provisionalMatches?: number;
  eliteK?: number;
  eliteRating?: number;
  botKMultiplier?: number;
  minRating?: number;
  maxRating?: number;
}

export interface RatingChange {
  playerId: PlayerId;
  place: number;
  ratingBefore: number;
  ratingAfter: number;
  /** Applied change after rounding and clamping. */
  delta: number;
  /** Unrounded change, useful for diagnostics and zero-sum checks. */
  rawDelta: number;
  expectedScore: number;
  actualScore: number;
  kFactor: number;
}

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));

/** Standard Elo expectation for a single pairing. */
export function expectedScore(rating: number, opponentRating: number): number {
  return 1 / (1 + Math.pow(10, (opponentRating - rating) / 400));
}

/** Fresh accounts move fast, elite accounts move slowly; bots can be damped further. */
export function kFactorFor(participant: RatingParticipant, options: RatingOptions = {}): number {
  const provisionalMatches = options.provisionalMatches ?? 10;
  const played = participant.matchesPlayed ?? provisionalMatches;
  let factor = options.baseK ?? 24;
  if (played < provisionalMatches) factor = options.provisionalK ?? 40;
  else if (participant.rating >= (options.eliteRating ?? 2200)) factor = options.eliteK ?? 16;
  if (participant.kind === 'bot') factor *= options.botKMultiplier ?? 1;
  return factor;
}

/**
 * Multiplayer Elo: each player is scored against every opponent in the lobby and the
 * pairwise results are averaged, so an eight player match stays comparable to a duel.
 * With equal K factors the raw deltas of a match sum to zero.
 */
export function computeMatchRatings(
  participants: readonly RatingParticipant[],
  options: RatingOptions = {},
): RatingChange[] {
  const minRating = options.minRating ?? 100;
  const maxRating = options.maxRating ?? 3500;
  const field = participants.length;
  const pairs = Math.max(field - 1, 1);

  return participants.map((participant, index) => {
    const kFactor = kFactorFor(participant, options);
    let expectedTotal = 0;
    let actualTotal = 0;

    participants.forEach((opponent, opponentIndex) => {
      if (opponentIndex === index) return;
      expectedTotal += expectedScore(participant.rating, opponent.rating);
      if (participant.place < opponent.place) actualTotal += 1;
      else if (participant.place === opponent.place) actualTotal += 0.5;
    });

    const expected = field < 2 ? 0.5 : expectedTotal / pairs;
    const actual = field < 2 ? 0.5 : actualTotal / pairs;
    const rawDelta = field < 2 ? 0 : kFactor * (actual - expected);
    const ratingAfter = clamp(Math.round(participant.rating + rawDelta), minRating, maxRating);

    return {
      playerId: participant.playerId,
      place: participant.place,
      ratingBefore: participant.rating,
      ratingAfter,
      delta: ratingAfter - participant.rating,
      rawDelta,
      expectedScore: expected,
      actualScore: actual,
      kFactor,
    };
  });
}

/** Bridges finished-match standings into rating input. */
export function participantsFromStandings(
  standings: readonly MatchStanding[],
  players: readonly PlayerProfile[],
  matchesPlayed?: ReadonlyMap<PlayerId, number>,
): RatingParticipant[] {
  return standings.map((standing) => {
    const player = players.find((candidate) => candidate.id === standing.playerId);
    const played = matchesPlayed?.get(standing.playerId);
    const participant: RatingParticipant = {
      playerId: standing.playerId,
      rating: player?.rating ?? DEFAULT_RATING,
      place: standing.rank,
    };
    if (player) participant.kind = player.kind;
    if (played !== undefined) participant.matchesPlayed = played;
    return participant;
  });
}

/** Returns copies of the profiles with the new ratings applied. */
export function applyRatingChanges(
  players: readonly PlayerProfile[],
  changes: readonly RatingChange[],
): PlayerProfile[] {
  return players.map((player) => {
    const change = changes.find((entry) => entry.playerId === player.id);
    return change ? { ...player, rating: change.ratingAfter } : { ...player };
  });
}
